from typing import List

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Starting cells: (i, 0) for all i, and (0, j) for j >= 1
        starts = [(i, 0) for i in range(n)] + [(0, j) for j in range(1, n)]
        for si, sj in starts:
            cells = []
            i, j = si, sj
            while i < n and j < n:
                cells.append((i, j))
                i += 1
                j += 1
            vals = [grid[r][c] for r, c in cells]
            if si >= sj:
                vals.sort(reverse=True)
            else:
                vals.sort()
            for (r, c), v in zip(cells, vals):
                grid[r][c] = v
        return grid
