class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Group cells by diagonal index d = i - j
        diagonals = {}
        for i in range(n):
            for j in range(n):
                diagonals.setdefault(i - j, []).append((i, j))

        for d, cells in diagonals.items():
            vals = [grid[i][j] for i, j in cells]
            if d <= 0:
                # bottom-left triangle including main diagonal: non-increasing
                vals.sort(reverse=True)
            else:
                # top-right triangle: non-decreasing
                vals.sort()
            for (i, j), v in zip(cells, vals):
                grid[i][j] = v
        return grid
